WITH __x360_opportunity_count_request_dates AS (
 -- 接收页面日期参数以维持筛选契约；按已确认口径，不用缺失的审批时间过滤商机。
 SELECT NULL::timestamp AS start_at,NULL::timestamp AS end_at
 /*TIME_BEGIN*/ WHERE FALSE UNION ALL SELECT CAST(:start_date AS timestamp),CAST(:end_exclusive AS timestamp) /*TIME_END*/
)
SELECT __x360_count_result.* FROM (
WITH __x360_gov_source_1 AS NOT MATERIALIZED (SELECT __x360_raw."project_name",__x360_raw."input_time",__x360_raw."seq_no" AS "bid_record_id" FROM ded_public."p_fm_bid_project_info" __x360_raw)
SELECT * FROM (
WITH opp AS (SELECT DISTINCT o.opportunityid,o.new_approved_time::timestamp AS fact_date,o.new_salesbg::text AS d002,CASE WHEN NULLIF(btrim(o.new_accproducttype::text),'') IS NULL THEN '其他' WHEN o.new_accproducttype::text IN ('1','电芯') THEN '电芯' WHEN o.new_accproducttype::text IN ('2','PACK') THEN 'PACK' ELSE '其他' END AS d003,o.ownerid AS owner_id,o.new_accountlevel::text AS d005,NULLIF(btrim(a.name::text),'') AS d006,EXISTS(SELECT 1 FROM __x360_gov_source_1 b WHERE b.project_name=o.name AND b.bid_record_id IS NOT NULL AND NULLIF(btrim(b.input_time::text),'') IS NOT NULL AND b.input_time::timestamp<=NOW()) AS entered FROM ded_public."p_fm_edw_v_ods_crm_opportunity_esb" o LEFT JOIN ded_public."p_fm_edw_v_ods_crm_account_esb" a ON a.accountid=o.parentaccountid WHERE o.opportunityid IS NOT NULL ), scoped AS (SELECT o.* FROM opp o WHERE TRUE   /*FILTER_BEGIN:YWLN_D002*/ AND o.d002 IN (:product_lines) /*FILTER_END:YWLN_D002*/ /*FILTER_BEGIN:YWLN_D003*/ AND o.d003 IN (:product_types) /*FILTER_END:YWLN_D003*/ /*FILTER_BEGIN:YWLN_D004*/ AND EXISTS(SELECT 1 FROM ded_public."p_fm_edw_v_ods_crm_teammembership_esb" tm JOIN ded_public."p_fm_edw_v_ods_crm_team_esb" team ON team."teamid"=tm."teamid" WHERE tm."systemuserid"=o.owner_id AND team."name"::text IN (:team_ids)) /*FILTER_END:YWLN_D004*/ /*FILTER_BEGIN:YWLN_D005*/ AND o.d005 IN (:customer_levels) /*FILTER_END:YWLN_D005*/ /*FILTER_BEGIN:YWLN_D006*/ AND o.d006 IN (:customer_ids) /*FILTER_END:YWLN_D006*/), counts AS (SELECT COUNT(*)::numeric AS total_count,COUNT(*) FILTER(WHERE entered)::numeric AS entered_count FROM scoped) SELECT (total_count-entered_count)::bigint AS "YWLN_M_NON_BIDDING_OPPORTUNITY_COUNT",(total_count-entered_count)/NULLIF(total_count,0) AS "YWLN_M_NON_BIDDING_OPPORTUNITY_SHARE" FROM counts
) AS __x360_gov_result
) __x360_count_result
/*X360_OPPORTUNITY_COUNT_IGNORE_APPROVAL_DATE_20261110*/

WITH __x360_gov_source_11 AS NOT MATERIALIZED (SELECT __x360_raw."salesorderid",__x360_raw."new_changetype",__x360_raw."new_changestatus",__x360_raw."new_salesordertype",__x360_raw."new_order_category",__x360_raw."new_salesorderid",__x360_raw."ownerid",__x360_raw."name",__x360_raw."opportunityid",__x360_raw."customerid",__x360_raw."statecode",__x360_raw."createdon",__x360_raw."new_approval_time",__x360_raw."new_amount" AS "order_amount_rmb_ex_tax" FROM ded_public."p_fm_edw_v_ods_crm_salesorder_esb" __x360_raw)
SELECT * FROM (
WITH order_distinct AS MATERIALIZED (
 SELECT DISTINCT so.salesorderid AS fact_id,so.createdon::timestamp AS fact_date,o.new_salesbg::text AS d002,
 CASE WHEN o.opportunityid IS NULL THEN NULL WHEN NULLIF(btrim(o.new_accproducttype::text),'') IS NULL THEN '其他' WHEN o.new_accproducttype IN ('1','电芯') THEN '电芯' WHEN o.new_accproducttype IN ('2','PACK') THEN 'PACK' ELSE '其他' END AS d003,
 o.ownerid AS owner_id,o.new_accountlevel::text AS d005,NULLIF(btrim(acc_so.name::text),'') AS d006,
 CASE WHEN so.statecode=2 THEN 'order_cancel' WHEN so.statecode=0 AND so.new_changestatus='8' THEN 'order_change' WHEN so.statecode=0 THEN 'normal_order' END AS status_code, CASE WHEN ((so.order_amount_rmb_ex_tax)::text)::text ~ '^[+-]?[0-9]+([.][0-9]+)?$' THEN ((so.order_amount_rmb_ex_tax)::text)::numeric END AS amount_yuan
 FROM __x360_gov_source_11 so LEFT JOIN ded_public."p_fm_edw_v_ods_crm_account_esb" acc_so ON acc_so.accountid = so.customerid LEFT JOIN ded_public."p_fm_edw_v_ods_crm_opportunity_esb" o ON o.opportunityid=so.opportunityid
 WHERE so.salesorderid IS NOT NULL /*TIME_BEGIN*/ AND so.createdon::timestamp>=CAST(:start_date AS timestamp) AND so.createdon::timestamp<CAST(:end_exclusive AS timestamp) /*TIME_END*/ 
), orders AS MATERIALIZED (SELECT *,COUNT(*) OVER(PARTITION BY fact_id) AS copies FROM order_distinct)
, fact_distinct AS (SELECT *,amount_yuan AS metric_value,(amount_yuan IS NULL) AS needs_value FROM orders WHERE status_code IN ('normal_order','order_change','order_cancel')), metric_facts AS (SELECT *,COUNT(*) OVER(PARTITION BY fact_id) AS metric_copies FROM fact_distinct)
, scoped AS (SELECT f.*,NULL::text AS d004 FROM metric_facts f  WHERE 1=1
 
 /*FILTER_BEGIN:YWLN_D002*/ AND f.d002 IN (:product_lines) /*FILTER_END:YWLN_D002*/
 /*FILTER_BEGIN:YWLN_D003*/ AND f.d003 IN (:product_types) /*FILTER_END:YWLN_D003*/
 /*FILTER_BEGIN:YWLN_D004*/ AND EXISTS (SELECT 1 FROM ded_public."p_fm_edw_v_ods_crm_teammembership_esb" tm JOIN ded_public."p_fm_edw_v_ods_crm_team_esb" t ON t."teamid"=tm."teamid"
 WHERE tm."systemuserid"=f.owner_id AND t."name"::text IN (:team_ids)) /*FILTER_END:YWLN_D004*/
 /*FILTER_BEGIN:YWLN_D005*/ AND /*YWLN_CUSTOMER_LEVEL_FILTER_V1*/ (f.d005::text IN (:customer_levels) OR (CASE f.d005::text WHEN '0' THEN '核心大客户' WHEN '1' THEN '战略大客户' WHEN '2' THEN '重要大客户' WHEN '3' THEN '一般客户' WHEN '4' THEN 'BG大客户' WHEN '战略大客户' THEN '战略大客户' WHEN '重要大客户' THEN '重要大客户' WHEN '一般客户' THEN '一般客户' WHEN 'BG大客户' THEN 'BG大客户' END) IN (:customer_levels)) /*FILTER_END:YWLN_D005*/
 /*FILTER_BEGIN:YWLN_D006*/ AND /*YWLN_CUSTOMER_NAME_FILTER_V1*/ (f.d006::text IN (:customer_ids) OR EXISTS (SELECT 1 FROM ded_public."p_fm_edw_v_ods_crm_account_esb" customer_filter WHERE customer_filter.accountid::text=f.d006::text AND NULLIF(btrim(customer_filter.name::text),'') IN (:customer_ids))) /*FILTER_END:YWLN_D006*/
 /*FILTER_BEGIN:YWLN_D016*/ AND f.status_code IN (:order_states) /*FILTER_END:YWLN_D016*/)
SELECT f.status_code AS "YWLN_D016", SUM(f.metric_value / NULLIF(f.metric_copies,0))/100000000::numeric AS "YWLN_M0033" FROM scoped f GROUP BY f.status_code
) AS __x360_gov_result

WITH __x360_opportunity_count_request_dates AS (
 -- 接收页面日期参数以维持筛选契约；按已确认口径，不用缺失的审批时间过滤商机。
 SELECT NULL::timestamp AS start_at,NULL::timestamp AS end_at
 /*TIME_BEGIN*/ WHERE FALSE UNION ALL SELECT CAST(:start_date AS timestamp),CAST(:end_exclusive AS timestamp) /*TIME_END*/
)
SELECT __x360_count_result.* FROM (
WITH __x360_gov_source_1 AS NOT MATERIALIZED (SELECT __x360_raw."project_name",__x360_raw."input_time",__x360_raw."seq_no" AS "bid_record_id" FROM ded_public."p_fm_bid_project_info" __x360_raw)
SELECT * FROM (
WITH opp AS (SELECT DISTINCT o.opportunityid,o.new_approved_time::timestamp AS fact_date,o.new_salesbg::text AS d002,CASE WHEN NULLIF(btrim(o.new_accproducttype::text),'') IS NULL THEN '其他' WHEN o.new_accproducttype::text IN ('1','电芯') THEN '电芯' WHEN o.new_accproducttype::text IN ('2','PACK') THEN 'PACK' ELSE '其他' END AS d003,o.ownerid AS owner_id,o.new_accountlevel::text AS d005,NULLIF(btrim(a.name::text),'') AS d006,EXISTS(SELECT 1 FROM __x360_gov_source_1 b WHERE b.project_name=o.name AND b.bid_record_id IS NOT NULL AND NULLIF(btrim(b.input_time::text),'') IS NOT NULL AND b.input_time::timestamp<=NOW()) AS entered FROM ded_public."p_fm_edw_v_ods_crm_opportunity_esb" o LEFT JOIN ded_public."p_fm_edw_v_ods_crm_account_esb" a ON a.accountid=o.parentaccountid WHERE o.opportunityid IS NOT NULL ), scoped AS (SELECT o.* FROM opp o WHERE TRUE   /*FILTER_BEGIN:YWLN_D002*/ AND o.d002 IN (:product_lines) /*FILTER_END:YWLN_D002*/ /*FILTER_BEGIN:YWLN_D003*/ AND o.d003 IN (:product_types) /*FILTER_END:YWLN_D003*/ /*FILTER_BEGIN:YWLN_D004*/ AND EXISTS(SELECT 1 FROM ded_public."p_fm_edw_v_ods_crm_teammembership_esb" tm JOIN ded_public."p_fm_edw_v_ods_crm_team_esb" team ON team."teamid"=tm."teamid" WHERE tm."systemuserid"=o.owner_id AND team."name"::text IN (:team_ids)) /*FILTER_END:YWLN_D004*/ /*FILTER_BEGIN:YWLN_D005*/ AND o.d005 IN (:customer_levels) /*FILTER_END:YWLN_D005*/ /*FILTER_BEGIN:YWLN_D006*/ AND o.d006 IN (:customer_ids) /*FILTER_END:YWLN_D006*/), counts AS (SELECT COUNT(*)::numeric AS total_count,COUNT(*) FILTER(WHERE entered)::numeric AS entered_count FROM scoped) SELECT entered_count::bigint AS "YWLN_M_BIDDING_OPPORTUNITY_COUNT",entered_count/NULLIF(total_count,0) AS "YWLN_M_BIDDING_OPPORTUNITY_SHARE" FROM counts
) AS __x360_gov_result
) __x360_count_result
/*X360_OPPORTUNITY_COUNT_IGNORE_APPROVAL_DATE_20261110*/
